60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner's email. An email whose domain
81	     * (the part after the {@code @}, compared case-insensitively) is on this blocklist is rejected.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
84	        "mailinator.com",
85	        "tempmail.com",
86	        "guerrillamail.com");
87	
88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code and registration date so the side-effect can be observed
91	     * independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys and values are
97	     * upper-cased so the mapping is applied after the address has been upper-cased.
98	     */
99	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
100	        "ST", "STREET",
101	        "RD", "ROAD",
102	        "AVE", "AVENUE");
103	
104	    /**
105	     * Maximum number of owners permitted in a single city. Once a city already contains this many
106	     * owners, creating another owner in that city is rejected as a conflict.
107	     */
108	    private static final int CITY_CAPACITY = 50;
109	
110	    /**
111	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
112	     * already share the current registration date, creating another owner today is rejected.
113	     */
114	    private static final int DAILY_OWNER_LIMIT = 100;
115	
116	    /**
117	     * Number of owner registrations on a single business day above which a newly created owner is
118	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
119	     * registration date, the surge is signalled in the response; the create itself still succeeds.
120	     */
121	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
122	
123	    /**
124	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
125	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
126	     * a city that is not listed has no known region and accepts any 4-digit postcode.
127	     */
128	    private static final Map<String, String> CITY_REGIONS = Map.of(
129	        "Sydney", "NSW",
130	        "Melbourne", "VIC",
131	        "Brisbane", "QLD");
132	
133	    /**
134	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
135	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
136	     */
137	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
138	        "NSW", new int[] {2000, 2099},
139	        "VIC", new int[] {3000, 3099},
140	        "QLD", new int[] {4000, 4099});
141	
142	    private final ClinicService clinicService;
143	
144	    private final OwnerMapper ownerMapper;
145	
146	    private final PetMapper petMapper;
147	
148	    private final VisitMapper visitMapper;
149	
150	    public OwnerRestControllerV1(ClinicService clinicService,
151	                                 OwnerMapper ownerMapper,
152	                                 PetMapper petMapper,
153	                                 VisitMapper visitMapper) {
154	        this.clinicService = clinicService;
155	        this.ownerMapper = ownerMapper;
156	        this.petMapper = petMapper;
157	        this.visitMapper = visitMapper;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
163	        Collection<Owner> owners;
164	        if (lastName != null) {
165	            owners = this.clinicService.findOwnerByLastName(lastName);
166	        } else {
167	            owners = this.clinicService.findAllOwners();
168	        }
169	        if (owners.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
183	    }
184	
185	    /**
186	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
187	     * upper-cases the value, and expands common street-type abbreviations word-by-word
188	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
189	     * normalizes to the empty string. The normalized value is what the application stores, returns
190	     * and compares for household detection.
191	     *
192	     * @param address the raw address value from the request, may be {@code null}
193	     * @return the normalized address, or the empty string when none was supplied
194	     */
195	    private String normalizeAddress(String address) {
196	        if (address == null) {
197	            return "";
198	        }
199	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
200	        if (collapsed.isEmpty()) {
201	            return "";
202	        }
203	        String[] tokens = collapsed.split(" ");
204	        StringBuilder normalized = new StringBuilder();
205	        for (int i = 0; i < tokens.length; i++) {
206	            if (i > 0) {
207	                normalized.append(' ');
208	            }
209	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
210	        }
211	        return normalized.toString();
212	    }
213	
214	    /**
215	     * Rejects an owner payload that is missing or blank in any required field. The response body's
216	     * {@code errors} array lists the name of each offending field.
217	     *
218	     * @param ownerFieldsDto the owner payload to validate
219	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
220	     */
221	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
222	        List<String> missingFields = new ArrayList<>();
223	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
224	            missingFields.add("firstName");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
227	            missingFields.add("lastName");
228	        }
229	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
230	            missingFields.add("address");
231	        }
232	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
233	            missingFields.add("city");
234	        }
235	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
236	            missingFields.add("telephone");
237	        }
238	        if (!missingFields.isEmpty()) {
239	            throw new RequiredFieldsMissingException(missingFields);
240	        }
241	    }
242	
243	    /**
244	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
245	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
246	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
247	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
248	     * region accepts any 4-digit postcode.
249	     *
250	     * @param postcode the raw postcode value from the request, may be {@code null}
251	     * @param city the owner's city, used to look up the region whose range constrains the postcode
252	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
253	     */
254	    private void validatePostcode(String postcode, String city) {
255	        if (postcode == null) {
256	            return;
257	        }
258	        if (!postcode.matches("[0-9]{4}")) {
259	            throw new InvalidFieldsException(List.of("postcode"));
260	        }
261	        String region = CITY_REGIONS.get(city);
262	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
263	        if (range != null) {
264	            int value = Integer.parseInt(postcode);
265	            if (value < range[0] || value > range[1]) {
266	                throw new InvalidFieldsException(List.of("postcode"));
267	            }
268	        }
269	    }
270	
271	    /**
272	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
273	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
274	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
275	     * followed by 8 to 15 digits.
276	     *
277	     * @param telephone the raw telephone value from the request
278	     * @return the E.164 telephone (e.g. {@code +61412345678})
279	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
280	     */
281	    private String normalizeTelephone(String telephone) {
282	        if (telephone == null) {
283	            throw new InvalidFieldsException(List.of("telephone"));
284	        }
285	        String trimmed = telephone.trim();
286	        boolean international = trimmed.startsWith("+");
287	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
288	        String digits;
289	        if (international) {
290	            digits = cleaned.substring(1);
291	        } else {
292	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
293	            digits = "61" + national;
294	        }
295	        if (!digits.matches("[0-9]{8,15}")) {
296	            throw new InvalidFieldsException(List.of("telephone"));
297	        }
298	        requireValidNationalLength(digits);
299	        return "+" + digits;
300	    }
301	
302	    /**
303	     * Country codes with a fixed national-number length, checked longest-prefix first so that
304	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
305	     * digits; the North American Numbering Plan ('1') requires 10.
306	     */
307	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
308	
309	    /**
310	     * Validates that the national number (the E.164 digits after the country code) has the length
311	     * required for its country. Country codes without a known fixed length are left to the general
312	     * E.164 length check.
313	     *
314	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
315	     * @throws InvalidFieldsException if the national number is the wrong length for its country
316	     */
317	    private void requireValidNationalLength(String digits) {
318	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
319	            .filter(entry -> digits.startsWith(entry.getKey()))
320	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
321	            .ifPresent(entry -> {
322	                int nationalLength = digits.length() - entry.getKey().length();
323	                if (nationalLength != entry.getValue()) {
324	                    throw new InvalidFieldsException(List.of("telephone"));
325	                }
326	            });
327	    }
328	
329	    /**
330	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
331	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
332	     * be a syntactically valid address; the accepted value is returned lower-cased.
333	     *
334	     * @param email the raw email value from the request, may be {@code null}
335	     * @return the lower-cased email, or {@code null} when none was supplied
336	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
337	     */
338	    private String normalizeEmail(String email) {
339	        if (email == null || email.isBlank()) {
340	            return null;
341	        }
342	        String trimmed = email.trim();
343	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
344	            throw new InvalidFieldsException(List.of("email"));
345	        }
346	        String normalized = trimmed.toLowerCase(Locale.ROOT);
347	        String domain = normalized.substring(normalized.indexOf('@') + 1);
348	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
349	            throw new InvalidFieldsException(List.of("email"));
350	        }
351	        return normalized;
352	    }
353	
354	    /**
355	     * Rejects an owner that collides with an existing owner on their derived identity key. All
356	     * duplicate detection is consolidated into this single key
357	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
358	     * the former separate telephone, email and household checks.
359	     *
360	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
361	     * share the same normalized telephone. Because the telephone is the leading, always-present part
362	     * of the key, two members of the same household with <em>different</em> telephones have different
363	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
364	     * scenario in the acceptance suite exercises - is rejected.
365	     *
366	     * @param owner the owner being created, with its normalized telephone and email already applied
367	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
368	     */
369	    private void requireUniqueIdentity(Owner owner) {
370	        String telephone = owner.getTelephone();
371	        boolean taken = this.clinicService.findAllOwners().stream()
372	            .map(Owner::getTelephone)
373	            .anyMatch(existing -> existing != null && existing.equals(telephone));
374	        if (taken) {
375	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
376	        }
377	    }
378	
379	    /**
380	     * Rejects an owner that would join an existing owner's household without opting in. The household
381	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
382	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
383	     * a last name and postcode belong to the same household even with different addresses or
384	     * telephones. Only owners with a postcode participate: an owner without a postcode has no
385	     * well-defined household and is never blocked here. The check is bypassed by the caller when the
386	     * request sets {@code sharesHousehold}, so a declared household member is created rather than
387	     * rejected.
388	     *
389	     * @param owner the owner being created, with its normalized fields already applied
390	     * @throws DuplicateOwnerHouseholdException if an existing owner already shares the household id
391	     */
392	    private void requireNoHouseholdDuplicate(Owner owner) {
393	        if (owner.getPostcode() == null) {
394	            return;
395	        }
396	        String householdId = ownerMapper.householdId(owner);
397	        boolean taken = this.clinicService.findAllOwners().stream()
398	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
399	        if (taken) {
400	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
401	        }
402	    }
403	
404	    /**
405	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
406	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
407	     * normalizes to the empty string.
408	     *
409	     * @param value the raw field value, may be {@code null}
410	     * @return the trimmed, whitespace-collapsed, lower-cased form
411	     */
412	    private String normalizeHousehold(String value) {
413	        if (value == null) {
414	            return "";
415	        }
416	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
417	    }
418	
419	    /**
420	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
421	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
422	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
423	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
424	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
425	     * returned so the result is deterministic.
426	     *
427	     * @param owner the owner being created, with its normalized telephone already applied
428	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
429	     */
430	    private Owner findPossibleDuplicate(Owner owner) {
431	        String lastName = owner.getLastName();
432	        String postcode = owner.getPostcode();
433	        if (lastName == null || postcode == null) {
434	            return null;
435	        }
436	        String telephone = owner.getTelephone();
437	        return this.clinicService.findAllOwners().stream()
438	            .filter(existing -> postcode.equals(existing.getPostcode()))
439	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
440	            .filter(existing -> existing.getTelephone() == null
441	                || !existing.getTelephone().equals(telephone))
442	            .min(Comparator.comparingInt(Owner::getId))
443	            .orElse(null);
444	    }
445	
446	    /**
447	     * Rejects an owner whose city already contains the maximum permitted number of owners
448	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
449	     * the same normalization used for the other owner household fields.
450	     *
451	     * @param city the city of the owner being created
452	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
453	     */
454	    private void requireCityHasCapacity(String city) {
455	        String normalizedCity = normalizeHousehold(city);
456	        long count = this.clinicService.findAllOwners().stream()
457	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
458	            .count();
459	        if (count >= CITY_CAPACITY) {
460	            throw new CityAtCapacityException(city);
461	        }
462	    }
463	
464	    /**
465	     * Rejects creating an owner once the given business day has already reached the maximum
466	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
467	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
468	     * registration date.
469	     *
470	     * @param registrationDate the business-day-adjusted registration date of the owner being created
471	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
472	     *     registered on that business day
473	     */
474	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
475	        long count = this.clinicService.findAllOwners().stream()
476	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
477	            .count();
478	        if (count >= DAILY_OWNER_LIMIT) {
479	            throw new DailyOwnerLimitException(registrationDate);
480	        }
481	    }
482	
483	    /**
484	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
485	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
486	     * been registered on that date. Evaluated before the new owner is persisted, so the count
487	     * reflects the owners that existed at the time of creation.
488	     *
489	     * @param registrationDate the business-day-adjusted registration date of the owner being created
490	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
491	     *     that registration date, otherwise {@code false}
492	     */
493	    private boolean isBulkSignup(LocalDate registrationDate) {
494	        long count = this.clinicService.findAllOwners().stream()
495	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
496	            .count();
497	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
498	    }
499	
500	    /**
501	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
502	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
503	     * date in the future is invalid.
504	     *
505	     * @param registrationDate the registration date supplied on the request, may be {@code null}
506	     * @throws InvalidFieldsException if the supplied date is later than today's server date
507	     */
508	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
509	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
510	            throw new InvalidFieldsException(List.of("registrationDate"));
511	        }
512	    }
513	
514	    /**
515	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
516	     * following Monday, while a weekday is returned unchanged.
517	     *
518	     * @param date the effective registration date (supplied or defaulted to the server date)
519	     * @return the same date when it is a weekday, otherwise the next Monday
520	     */
521	    private LocalDate toBusinessDay(LocalDate date) {
522	        return switch (date.getDayOfWeek()) {
523	            case SATURDAY -> date.plusDays(2);
524	            case SUNDAY -> date.plusDays(1);
525	            default -> date;
526	        };
527	    }
528	
529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
532	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
533	        validateRequiredFields(ownerFieldsDto);
534	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
535	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
536	        requireCityHasCapacity(ownerFieldsDto.getCity());
537	        String email = normalizeEmail(ownerFieldsDto.getEmail());
538	        HttpHeaders headers = new HttpHeaders();
539	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
540	        owner.setTelephone(telephone);
541	        owner.setEmail(email);
542	        requireUniqueIdentity(owner);
543	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
544	        if (!sharesHousehold) {
545	            requireNoHouseholdDuplicate(owner);
546	        }
547	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
548	        LocalDate effectiveDate = owner.getRegistrationDate() != null
549	            ? owner.getRegistrationDate() : LocalDate.now();
550	        LocalDate registrationDate = toBusinessDay(effectiveDate);
551	        owner.setRegistrationDate(registrationDate);
552	        requireDailyLimitNotReached(registrationDate);
553	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
554	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
555	        owner.setPossibleDuplicate(possibleDuplicate != null);
556	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
557	        this.clinicService.saveOwner(owner);
558	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
559	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
560	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
561	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
562	        headers.setLocation(UriComponentsBuilder.newInstance()
563	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
564	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
570	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
571	        if (currentOwner == null) {
572	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
573	        }
574	        currentOwner.setAddress(ownerFieldsDto.getAddress());
575	        currentOwner.setCity(ownerFieldsDto.getCity());
576	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
577	        currentOwner.setLastName(ownerFieldsDto.getLastName());
578	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
579	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
580	        this.clinicService.saveOwner(currentOwner);
581	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
582	    }
583	
584	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
585	    @Transactional
586	    @Override
587	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
588	        Owner owner = this.clinicService.findOwnerById(ownerId);
589	        if (owner == null) {
590	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
591	        }
592	        this.clinicService.deleteOwner(owner);
593	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
594	    }
595	
596	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
597	    @Override
598	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
599	        Owner owner = this.clinicService.findOwnerById(ownerId);
600	        if (owner == null) {
601	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
602	        }
603	        HttpHeaders headers = new HttpHeaders();
604	        Pet pet = petMapper.toPet(petFieldsDto);
605	        owner.setId(ownerId);
606	        pet.setOwner(owner);
607	        pet.getType().setName(null);
608	        this.clinicService.savePet(pet);
609	        PetDto petDto = petMapper.toPetDto(pet);
610	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
611	            .buildAndExpand(pet.getId()).toUri());
612	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
618	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
619	        if (currentOwner != null) {
620	            Pet currentPet = this.clinicService.findPetById(petId);
621	            if (currentPet != null) {
622	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
623	                currentPet.setName(petFieldsDto.getName());
624	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
625	                this.clinicService.savePet(currentPet);
626	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
627	            }
628	        }
629	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
635	        HttpHeaders headers = new HttpHeaders();
636	        Visit visit = visitMapper.toVisit(visitFieldsDto);
637	        Pet pet = new Pet();
638	        pet.setId(petId);
639	        visit.setPet(pet);
640	        this.clinicService.saveVisit(visit);
641	        VisitDto visitDto = visitMapper.toVisitDto(visit);
642	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
643	            .buildAndExpand(visit.getId()).toUri());
644	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
645	    }
646	
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
651	        Owner owner = this.clinicService.findOwnerById(ownerId);
652	        if (owner != null) {
653	            Pet pet = owner.getPet(petId);
654	            if (pet != null) {
655	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
656	            }
657	        }
658	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
659	    }
660	}
