49	     *
50	     * @param owner the owner to derive the age band for
51	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
52	     *     is held
53	     */
54	    default String ageBand(Owner owner) {
55	        java.time.LocalDate birthDate = owner.getBirthDate();
56	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
57	        if (birthDate == null || registrationDate == null) {
58	            return null;
59	        }
60	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
61	        if (age < 18) {
62	            return "MINOR";
63	        }
64	        return age < 65 ? "ADULT" : "SENIOR";
65	    }
66	
67	    /**
68	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
69	     * email, otherwise {@code "PHONE"}.
70	     *
71	     * @param owner the owner to derive the contact preference for
72	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
73	     */
74	    default String contactPreference(Owner owner) {
75	        String email = owner.getEmail();
76	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
77	    }
78	
79	    /**
80	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
81	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
82	     * normalizing telephones into E.164 form.
83	     */
84	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
85	
86	    /**
87	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
88	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
89	     * The country code is taken as the longest recognized prefix (see
90	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
91	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
92	     * is returned unchanged.
93	     *
94	     * @param owner the owner to format the telephone display for
95	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
96	     *     digit string
97	     */
98	    default String telephoneDisplay(Owner owner) {
99	        String telephone = owner.getTelephone();
100	        if (telephone == null || !telephone.startsWith("+")) {
101	            return telephone;
102	        }
103	        String digits = telephone.substring(1);
104	        if (!digits.matches("[0-9]+")) {
105	            return telephone;
106	        }
107	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
108	            .filter(digits::startsWith)
109	            .max(java.util.Comparator.comparingInt(String::length))
110	            .orElseGet(() -> digits.substring(0, 1));
111	        String national = digits.substring(countryCode.length());
112	        StringBuilder sb = new StringBuilder("+").append(countryCode);
113	        for (int i = 0; i < national.length(); i += 3) {
114	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
115	        }
116	        return sb.toString();
117	    }
118	
119	    /**
120	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
121	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
122	     * the customer code's region is itself derived from the postcode (falling back to the city), the
123	     * locality now moves with the identity rather than being computed independently. The result is
124	     * {@code "UNKNOWN"} when no customer code is present.
125	     *
126	     * @param owner the owner to derive the locality for
127	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
128	     */
129	    default String locality(Owner owner) {
130	        String code = owner.getCustomerCode();
131	        if (code == null || code.isEmpty()) {
132	            return "UNKNOWN";
133	        }
134	        int dash = code.indexOf('-');
135	        return dash < 0 ? code : code.substring(0, dash);
136	    }
137	
138	    /**
139	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
140	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
141	     */
142	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
143	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
144	
145	    /**
146	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
147	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
148	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
149	     * the field is omitted from the response.
150	     *
151	     * @param owner the owner to derive the timezone for
152	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
153	     */
154	    default String timezone(Owner owner) {
155	        return REGION_TIMEZONES.get(locality(owner));
156	    }
157	
158	    /**
159	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
160	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
161	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
162	     * than {@code 365} days - the number of days between the owner's registration date and the
163	     * current server date. Because a newly created owner registers on the current date, its tenure
164	     * is zero, so a new owner never earns the tenure points.
165	     *
166	     * @param owner the owner to derive the membership points for
167	     * @return the membership points, {@code 0} or more
168	     */
169	    default Integer membershipPoints(Owner owner) {
170	        int points = 0;
171	        String email = owner.getEmail();
172	        if (email != null && !email.isBlank()) {
173	            points += 2;
174	        }
175	        Integer namesakeCount = owner.getNamesakeCount();
176	        if (namesakeCount != null && namesakeCount == 0) {
177	            points += 1;
178	        }
179	        Integer householdMemberCount = owner.getHouseholdMemberCount();
180	        if (householdMemberCount != null && householdMemberCount >= 3) {
181	            points += 2;
182	        }
183	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
184	        long tenureDays = registrationDate == null ? 0
185	            : java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
186	        if (tenureDays > 365) {
187	            points += 3;
188	        }
189	        return points;
190	    }
191	
192	    /**
193	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
194	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
195	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more.
196	     *
197	     * @param owner the owner to derive the membership level for
198	     * @return the membership level, between {@code 1} and {@code 4}
199	     */
200	    default Integer membershipLevel(Owner owner) {
201	        int points = membershipPoints(owner);
202	        if (points <= 1) {
203	            return 1;
204	        }
205	        if (points <= 3) {
206	            return 2;
207	        }
208	        if (points <= 5) {
209	            return 3;
210	        }
211	        return 4;
212	    }
213	
214	    /**
215	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
216	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
217	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
218	     *
219	     * @param owner the owner to derive the membership number for
220	     * @return the formatted membership number
221	     */
222	    default String membershipNumber(Owner owner) {
223	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
224	        return owner.getCustomerCode() + "-M" + yy;
225	    }
226	
227	    /**
228	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
229	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
230	     * are ignored.
231	     *
232	     * @param owner the owner to derive the check digit for
233	     * @return the Luhn check digit, between {@code 0} and {@code 9}
234	     */
235	    default Integer checkDigit(Owner owner) {
236	        String code = owner.getCustomerCode();
237	        int sum = 0;
238	        boolean dbl = true;
239	        for (int i = code.length() - 1; i >= 0; i--) {
240	            char c = code.charAt(i);
241	            if (c < '0' || c > '9') {
242	                continue;
243	            }
244	            int d = c - '0';
245	            if (dbl) {
246	                d *= 2;
247	                if (d > 9) {
248	                    d -= 9;
249	                }
250	            }
251	            sum += d;
252	            dbl = !dbl;
253	        }
254	        return (10 - (sum % 10)) % 10;
255	    }
256	
257	    /**
258	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
259	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
260	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
261	     * string. Because it is derived deterministically from the last name and postcode, every owner
262	     * that shares those two fields receives the same value - including owners created via the
263	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
264	     *
265	     * @param owner the owner to derive the household identifier for
266	     * @return the 12 upper-case hex character household identifier, never blank
267	     */
268	    default String householdId(Owner owner) {
269	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
270	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
271	        try {
272	            byte[] digest = MessageDigest.getInstance("SHA-256")
273	                .digest(key.getBytes(StandardCharsets.UTF_8));
274	            StringBuilder sb = new StringBuilder(12);
275	            for (int i = 0; i < 6; i++) {
276	                sb.append(String.format("%02X", digest[i]));
277	            }
278	            return sb.toString();
279	        }
280	        catch (NoSuchAlgorithmException ex) {
281	            throw new IllegalStateException("SHA-256 not available", ex);
282	        }
283	    }
284	
285	    /**
286	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
287	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
288	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
289	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
290	     * whole identity keys are equal; because the telephone is part of the key, household members with
291	     * different telephones have different keys.
292	     *
293	     * @param owner the owner to derive the identity key for
294	     * @return the {@code telephone|email|householdId} identity key
295	     */
296	    default String identityKey(Owner owner) {
297	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
298	        String email = owner.getEmail() == null ? "" : owner.getEmail();
299	        return telephone + '|' + email + '|' + householdId(owner);
300	    }
301	
302	    /**
303	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
304	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
305	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
306	     *
307	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
308	     * conversion and apply it to unrelated String properties (last name, address, ...).
309	     */
310	    private String normalizeHouseholdField(String value) {
311	        if (value == null) {
312	            return "";
313	        }
314	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
315	    }
316	
317	    Owner toOwner(OwnerDto ownerDto);
318	
319	    @Mapping(target = "id", ignore = true)
320	    @Mapping(target = "pets", ignore = true)
321	    Owner toOwner(OwnerFieldsDto ownerDto);
322	
323	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
324	
325	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
326	
327	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
328	        OwnerPageDto ownerPageDto = new OwnerPageDto();
329	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
330	        ownerPageDto.setPage(ownerPage.getNumber());
331	        ownerPageDto.setSize(ownerPage.getSize());
332	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
333	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
334	        return ownerPageDto;
335	    }
336	}
