300	     * 8 upper-case hex characters of the SHA-256 digest over the owner's normalized telephone
301	     * concatenated with the owner's last name. There is no sequence number: the identity is
302	     * derived entirely from the region and the telephone/last-name hash.
303	     */
304	    private String generateCustomerCode(Owner owner) {
305	        String base = regionFor(owner) + "-" + hash8(owner);
306	        return deduplicateCustomerCode(base);
307	    }
308	
309	    /**
310	     * Ensure the computed customer code is unique across existing owners. When the base code
311	     * collides with an existing owner's {@code customerCode}, append {@code '-<n>'} with the
312	     * smallest {@code n} of 2 or more that makes it unique, and return that de-duplicated code.
313	     */
314	    private String deduplicateCustomerCode(String base) {
315	        Set<String> existing = ownerRepository.findAll().stream()
316	            .map(Owner::getCustomerCode)
317	            .filter(code -> code != null)
318	            .collect(java.util.stream.Collectors.toSet());
319	        if (!existing.contains(base)) {
320	            return base;
321	        }
322	        int n = 2;
323	        while (existing.contains(base + "-" + n)) {
324	            n++;
325	        }
326	        return base + "-" + n;
327	    }
328	
329	    /**
330	     * Derive the owner's region, preferring the postcode over the city. The postcode is looked up
331	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
332	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
333	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
334	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither
335	     * the postcode nor the city resolves to a region.
336	     */
337	    private String regionFor(Owner owner) {
338	        String region = regionFromPostcode(owner.getPostcode());
339	        if (region != null) {
